package test;


import cn.hutool.json.JSONUtil;
import com.datasophon.dao.entity.ClusterHostDO;
import com.datasophon.k8s.util.KubeUtil;
import io.fabric8.kubernetes.api.model.Node;
import io.fabric8.kubernetes.api.model.NodeList;
import io.fabric8.kubernetes.client.KubernetesClient;
import org.junit.Test;

import java.util.List;

public class TestKube {

    private final static String KUBE_CONFIG =
            "apiVersion: v1\n" +
                "clusters:\n" +
                "- cluster:\n" +
                "    certificate-authority-data: \n" +
                "    server: https://192.168.1.203:6443\n" +
                "  name: kubernetes\n" +
                "contexts:\n" +
                "- context:\n" +
                "    cluster: kubernetes\n" +
                "    user: admin\n" +
                "  name: kubernetes\n" +
                "current-context: kubernetes\n" +
                "kind: Config\n" +
                "preferences: {}\n" +
                "users:\n" +
                "- name: admin\n" +
                "  user:\n" +
                "    client-certificate-data: \n" +
                "    client-key-data: \n";

    public static KubernetesClient getClient() {
        KubeUtil kubeUtil = new KubeUtil();
        return kubeUtil.getKubeClientByConfig(KUBE_CONFIG);
    }

    @Test
    public void test() {
        KubernetesClient client = getClient();
        NodeList list = client.nodes().list();
        List<Node> items = list.getItems();
        System.out.println(JSONUtil.toJsonStr(items));
    }

    @Test
    public void testNodeList() {
        KubeUtil kubeUtil = new KubeUtil();
        List<ClusterHostDO> list = kubeUtil.getHostListByConfig(1);
        System.out.println(JSONUtil.toJsonStr(list));
    }
}
